WITH filtered AS (SELECT id, store_id, product_id, sale_date, DATE_ADD(sale_date, 63) sale_date_plus_63d, DATEDIFF(CURRENT_DATE(), sale_date) days_since_sale_date FROM store_sales WHERE sale_date >= TO_DATE('2023-07-01')), ranked AS (SELECT * FROM filtered QUALIFY ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY days_since_sale_date DESC, id) = 1), scored AS (SELECT *, SUM(days_since_sale_date) OVER (PARTITION BY MONTH(sale_date_plus_63d), store_id ORDER BY sale_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_days_since_sale_date, AVG(days_since_sale_date) OVER (PARTITION BY store_id ORDER BY sale_date, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) days_since_sale_date_avg_3, NTILE(5) OVER (PARTITION BY product_id, store_id ORDER BY days_since_sale_date, id) days_since_sale_date_bucket, SUM(days_since_sale_date) OVER (PARTITION BY store_id ORDER BY sale_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_days_since_sale_date_2, SUM(days_since_sale_date) OVER (ORDER BY sale_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_days_since_sale_date_3 FROM ranked), cleaned AS (SELECT id, store_id, sale_date, sale_date_plus_63d, days_since_sale_date, days_since_sale_date_avg_3, ROUND(running_days_since_sale_date_3 / days_since_sale_date_bucket, 2) running_days_since_sale_date_3_per_days_since_sale_date_bucket FROM scored WHERE sale_date > DATE '2023-09-05') SELECT s.id, s.store_id, s.sale_date_plus_63d, s.days_since_sale_date, s.days_since_sale_date_avg_3, s.running_days_since_sale_date_3_per_days_since_sale_date_bucket, (SELECT MIN(t2.quantity) FROM inventory t2 WHERE t2.store_id = s.store_id) AS min_inventory_quantity FROM cleaned s;
